def Phi(x):
 return 0.5*math.erfc(-x/math.sqrt(2))
def normal_pdf(x):
 return math.exp(-x*x/2)/math.sqrt(2*math.pi)
def integrate(f,lo=-10,hi=10,steps=20000):
 h=(hi-lo)/steps
 return h/3*(f(lo)+f(hi)+sum((4 if k%2 else 2)*f(lo+k*h) for k in range(1,steps)))
v1,v2=1,2
log_ratio=math.log(v2/v1)
b=1/v1-1/v2
risk1=integrate(lambda t: normal_pdf(t)*Phi(-0.5-0.5*log_ratio+0.5*b*v1*t*t))
risk2=integrate(lambda t: normal_pdf(t)*Phi(-0.5+0.5*log_ratio-0.5*b*v2*t*t))
print('QDA counterexample, retained-coordinate optimal risk:',Phi(-0.5))
print('QDA counterexample, limiting full Bayes risk:',(risk1+risk2)/2)
